<div x-show="proposals.length"><h2 class="text-lg font-semibold mb-3 flex items-center gap-2"><x-badge style="secondary" class="bg-accent text-foreground">Proposal</x-badge>Judul yang Anda Usulkan</h2><div class="grid gap-4"><template x-for="proposal in proposals" :key="proposal.id"><x-card class="relative border-l-4 border-l-primary"><div class="px-6 pb-3 flex justify-between items-start gap-3"><div><h3 class="font-semibold text-base" x-text="proposal.title"></h3><p class="text-sm text-muted-foreground">Calon Pembimbing: <span x-text="person(proposal.proposed_supervisor)"></span></p></div><x-badge style="secondary" ::class="badge(proposal.supervisor_approval_status)" x-text="proposal.supervisor_approval_status" /></div><div class="px-6 pb-3"><p class="text-sm text-muted-foreground line-clamp-2" x-text="proposal.description"></p></div></x-card></template></div></div>
